'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var abs = require( '@stdlib/math/base/special/abs' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var EPS = require( '@stdlib/constants/float64/eps' );
var factory = require( './../lib/factory.js' );


// FIXTURES //

var data = require( './fixtures/julia/data.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof factory, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a function', function test( t ) {
	var mgf = factory( 1.0 );
	t.strictEqual( typeof mgf, 'function', 'returns expected value' );
	t.end();
});

tape( 'if provided `NaN` for any parameter, the created function returns `NaN`', function test( t ) {
	var mgf;
	var y;

	mgf = factory( 1.0 );
	y = mgf( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( NaN );
	y = mgf( 0.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( NaN );
	y = mgf( NaN );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided a nonpositive `sigma`, the created function always returns `NaN`', function test( t ) {
	var mgf;
	var y;

	mgf = factory( 0.0 );
	y = mgf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( -1.0 );
	y = mgf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	mgf = factory( NINF );
	y = mgf( 2.0 );
	t.strictEqual( isnan( y ), true, 'returns expected value' );

	t.end();
});

tape( 'the created function evaluates the MGF for Half-normal distribution', function test( t ) {
	var expected;
	var delta;
	var sigma;
	var mgf;
	var tol;
	var x;
	var y;
	var i;

	expected = data.expected;
	x = data.t;
	sigma = data.sigma;

	for ( i = 0; i < x.length; i++ ) {
		mgf = factory( sigma[i] );
		y = mgf( x[i] );

		if ( expected[i] !== null ) {
			if ( y === expected[i] ) {
				t.strictEqual( y, expected[i], 'x: '+x[i]+', sigma: '+sigma[i]+', y: '+y+', expected: '+expected[i] );
			} else {
				delta = abs( y - expected[i] );
				tol = 700.0 * EPS * abs( expected[i] );
				t.ok( isAlmostSameValue( y, expected[i], 1500 ), 'within tolerance. x: '+x[ i ]+'. sigma: '+sigma[ i ]+'. y: '+y+'. E: '+expected[ i ]+'. Δ: '+delta+'. tol: '+tol+'.' );
			}
		}
	}
	t.end();
});
